import { Socket } from '@/libs/socket';
import { productCart, productHot, productVisit } from '@/api/kefu.js';
import { serviceInfo } from '@/api/kefu_mobile';
import empty from "../../components/empty";
export default {
  name: 'product_info',
  components: {
    empty: empty
  },
  data: function data() {
    return {
      ops: {
        bar: {
          background: '#393232',
          opacity: '.5',
          size: '2px'
        }
      },
      searchTxt: '',
      tabCur: 0,
      tabList: [{
        key: 0,
        title: '购买',
        api: 'productCart'
      }, {
        key: 1,
        title: '足迹',
        api: 'productHot'
      }, {
        key: 2,
        title: '热销',
        api: 'productVisit'
      }],
      toUid: '',
      list: []
    };
  },
  watch: {
    tabCur: function tabCur(nVal, oVal) {
      this.list = [];
      if (nVal == 0) return this.getBuyList();
      if (nVal == 1) return this.getVisit();
      if (nVal == 2) return this.getProductHot();
    }
  },
  created: function created() {
    serviceInfo().then(function (res) {
      window.document.title = "".concat(res.data.site_name, " - \u5546\u54C1\u5217\u8868");
    });
    this.toUid = this.$route.query.toUid;
    this.getBuyList();
  },
  methods: {
    // 购买记录
    getBuyList: function getBuyList() {
      var _this = this;
      productCart(this.toUid, {
        store_name: this.searchTxt
      }).then(function (res) {
        _this.list = res.data;
      });
    },
    // 热销商品
    getProductHot: function getProductHot() {
      var _this2 = this;
      productHot(this.toUid, {
        store_name: this.searchTxt
      }).then(function (res) {
        _this2.list = res.data;
      });
    },
    // 足迹
    getVisit: function getVisit() {
      var _this3 = this;
      productVisit(this.toUid, {
        store_name: this.searchTxt
      }).then(function (res) {
        _this3.list = res.data;
      });
    },
    // 推送
    bingGoods: function bingGoods(item) {
      var obj = {
        type: 'chat',
        data: {
          msn: item.id,
          type: 5,
          to_uid: this.toUid
        }
      };
      this.bus.pageWs.then(function (ws) {
        ws.send(obj);
      });
      // this.bus.$emit('selectGoods',item)
      this.$router.go(-1);
    },
    // 顶部选项卡切换
    bindTab: function bindTab(item) {
      this.tabCur = item.key;
    },
    // 搜索
    bindSearch: function bindSearch() {
      if (this.tabCur == 0) return this.getBuyList();
      if (this.tabCur == 1) return this.getVisit();
      if (this.tabCur == 2) return this.getProductHot();
    }
  }
};
